function boxBlurF(src,w,h,radius){
  var r=Math.max(0,Math.round(radius));
  if(r===0){ var c=new Float32Array(src.length); for(var i=0;i<src.length;i++)c[i]=src[i]; return c; }
  var out=new Float32Array(src.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var s=0,n=0;
    for(var yy=Math.max(0,y-r);yy<=Math.min(h-1,y+r);yy++) for(var xx=Math.max(0,x-r);xx<=Math.min(w-1,x+r);xx++){ s+=src[yy*w+xx]; n++; }
    out[y*w+x]=s/n;
  }
  return out;
}
function hueRGB(hh){ var c=1,x=(1-Math.abs((hh/60)%2-1)), m=0,r,g,b; if(hh<60){r=c;g=x;}else if(hh<120){r=x;g=c;}else if(hh<180){g=c;b=x;}else if(hh<240){g=x;b=c;}else if(hh<300){r=x;b=c;}else{r=c;b=x;} return [r+m,g+m,b+m]; }
function neonProcess(data,w,h,opts){
  opts=opts||{};
  var thr=opts.thr!=null?opts.thr:40;
  var glow=opts.glow!=null?opts.glow:6;
  var hue=opts.hue!=null?opts.hue:180;
  if(thr<0)thr=0; else if(thr>150)thr=150;
  if(glow<0)glow=0; else if(glow>20)glow=20;
  if(hue<0)hue=0; else if(hue>360)hue=360;
  var lum=new Float32Array(w*h);
  for(var i=0,y=0;y<h;y++) for(var x=0;x<w;x++,i++){ var p=(y*w+x)*4; lum[i]=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  function L(x,y){ if(x<0)x=0; else if(x>w-1)x=w-1; if(y<0)y=0; else if(y>h-1)y=h-1; return lum[y*w+x]; }
  var edge=new Float32Array(w*h);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var gx=L(x-1,y-1)+2*L(x-1,y)+L(x-1,y+1)-L(x+1,y-1)-2*L(x+1,y)-L(x+1,y+1);
    var gy=L(x-1,y-1)+2*L(x,y-1)+L(x+1,y-1)-L(x-1,y+1)-2*L(x,y+1)-L(x+1,y+1);
    edge[y*w+x]=Math.sqrt(gx*gx+gy*gy);
  }
  var mask=new Float32Array(w*h);
  for(var i2=0;i2<w*h;i2++){ mask[i2]= edge[i2]>thr ? Math.min(1,(edge[i2]-thr)/60) : 0; }
  var glowm=boxBlurF(mask,w,h,glow);
  var col=hueRGB(hue);
  var out=new Uint8ClampedArray(data.length);
  for(var i3=0,y=0;y<h;y++) for(var x=0;x<w;x++,i3++){
    var p=(y*w+x)*4;
    var g=glowm[i3];
    var core=mask[i3];
    var inten=Math.min(1, g*0.8+core);
    out[p]=8+col[0]*inten*255;
    out[p+1]=10+col[1]*inten*255;
    out[p+2]=18+col[2]*inten*255;
    out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={neonProcess:neonProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.NeonForgePure = EXPORTS; }
